local painted, models = 0, 0
local function paint(model, key)
	local map = COLORS[key]
	if not map then
		return
	end
	models += 1
	for _, d in ipairs(model:GetDescendants()) do
		if d:IsA("MeshPart") then
			local c = map[d.Name] or (d.Parent and map[(d.Parent.Name:gsub("_Node$", ""))])
			if c then
				d.Color = Color3.fromHex(c[1])
				d.Material = c[2] and Enum.Material.Neon or Enum.Material.SmoothPlastic
				d.Transparency = c[3] and (1 - c[3]) or 0
				painted += 1
			end
		end
	end
end

local cannons = game.ReplicatedStorage:FindFirstChild("Cannons")
if cannons then
	for _, m in ipairs(cannons:GetChildren()) do
		if not m:GetAttribute("Placeholder") then
			paint(m, m.Name)
		end
	end
end
local stations = workspace:FindFirstChild("TrainingStations")
if stations then
	local Config = require(game.ReplicatedStorage.GameConfig)
	for _, info in ipairs(Config.Stations) do
		local s = stations:FindFirstChild("Station_" .. info.Id)
		local c = s and s:FindFirstChild("Cannon")
		if c then
			paint(c, info.Model)
		end
	end
end
print("[ColorImportedCannons] painted " .. painted .. " parts on " .. models .. " cannons")
return painted
